export const genres=['소설','에세이','인문','자기계발','예술','과학'];
export const uid=()=>crypto.randomUUID();
export function seed(){const users=[{id:'u1',email:'demo@bookit.kr',nickname:'서연',bio:'책장에 머문 이야기가, 다른 누군가에게 닿기를.',contact:'demo@bookit.kr',method:'이메일',interests:['소설','에세이'],keywords:'여행 위로',avatar:''},{id:'u2',email:'green@bookit.kr',nickname:'초록책장',bio:'느리게 읽고 오래 기억해요.',contact:'green@bookit.kr',method:'이메일',interests:['소설','인문'],keywords:'',avatar:''},{id:'u3',email:'moon@bookit.kr',nickname:'달빛독서',bio:'좋은 문장을 함께 나눠요.',contact:'moon@bookit.kr',method:'이메일',interests:['에세이'],keywords:'',avatar:''}]; const titles=[['여행의 이유','김영하','에세이','여행에서 발견한 삶의 작은 순간들.','essay','새로운 곳으로 떠나기 전, 소설과 교환하고 싶어요.'],['불편한 편의점','김호연','소설','작은 편의점에서 시작되는 따뜻한 위로.','store','마음이 따뜻해지는 에세이를 찾고 있어요.'],['물고기는 존재하지 않는다','룰루 밀러','과학','질서와 혼돈 사이에서 발견하는 삶의 의미.','fish','인문·과학 분야 책을 환영해요.'],['아주 희미한 빛으로도','최은영','소설','우리 곁에 남은 관계와 다정함에 관한 이야기.','light','좋은 소설이나 에세이와 교환해요.'],['사피엔스','유발 하라리','인문','인류의 역사를 새롭게 바라보는 시선.','sapiens','인문 분야 또는 역사책을 찾습니다.'],['작별하지 않는다','한강','소설','기억과 사랑, 끝내 남아 있는 마음.','winter','소설과 교환하고 싶어요.'],['모든 삶은 흐른다','로랑스 드빌레르','인문','바다에서 배우는 삶의 태도.','sea','에세이 또는 여행책을 원해요.'],['나는 메트로폴리탄 미술관의 경비원입니다','패트릭 브링리','예술','예술과 함께 다시 시작하는 일상.','art','예술이나 에세이 분야를 좋아해요.']];return {version:1,users,books:titles.map((x,i)=>({id:'b'+i,owner:i===7?'u1':i%2?'u2':'u3',title:x[0],author:x[1],genre:x[2],description:x[3],cover:x[4],condition:i%3===0?'새 책':'좋음',terms:x[5],contact:users[i===7?0:i%2?1:2].contact,method:'이메일',created:Date.now()-i*86400000,status:'available'})),requests:[]};}
export function recommend(data,user){if(!user)return [];const mine=data.books.filter(b=>b.owner===user.id);return data.books.filter(b=>b.owner!==user.id&&b.status==='available').map(b=>{let score=0,reasons=[];if(user.interests.includes(b.genre)){score+=5;reasons.push('선호 장르와 일치해요');}const words=(user.keywords||'').split(/\s+/).filter(Boolean);if(words.some(w=>(b.title+b.description).includes(w))){score+=3;reasons.push('관심 키워드와 잘 맞아요');}if(mine.some(m=>b.terms.includes(m.genre)||m.terms.includes(b.genre))){score+=2;reasons.push('등록한 책의 교환 조건과 잘 맞아요');}return {...b,score,reason:reasons.join(' · ')||'새로운 독서 취향을 만나보세요'};}).sort((a,b)=>b.score-a.score);}
export function propose(data,user,target,offered,message){const b=data.books.find(b=>b.id===target),o=data.books.find(b=>b.id===offered);if(!b||!o||b.owner===user||o.owner!==user||b.status!=='available'||o.status!=='available')throw Error('교환 가능한 내 책과 상대방 책을 선택해주세요.');if(data.requests.some(r=>r.from===user&&r.to===b.owner&&['대기 중','수락됨'].includes(r.status)))throw Error('이 사용자에게 진행 중인 신청이 있어요.');const r={id:uid(),from:user,to:b.owner,target,offered,message,created:Date.now(),status:'대기 중',notes:{},confirmations:[]};data.requests.push(r);return r;}
export function transition(data,id,user,action){const r=data.requests.find(r=>r.id===id);if(!r||![r.from,r.to].includes(user))throw Error('접근할 수 없는 신청입니다.');if(action==='수락됨'){if(r.to!==user||r.status!=='대기 중')throw Error('수락할 수 없는 신청입니다.');const ids=[r.target,r.offered];if(ids.some(id=>data.books.find(b=>b.id===id)?.status!=='available'))throw Error('이미 예약되거나 교환된 책입니다.');r.status=action;data.books.filter(b=>ids.includes(b.id)).forEach(b=>b.status='reserved');data.requests.filter(x=>x.id!==id&&x.status==='대기 중'&&[x.target,x.offered].some(v=>ids.includes(v))).forEach(x=>{x.status='거절됨';x.closedReason='다른 교환이 수락되어 마감되었어요.';});}else if(action==='거절됨'||action==='취소됨'){if(r.status!=='대기 중'||(action==='거절됨'?r.to!==user:r.from!==user))throw Error('변경할 수 없는 신청입니다.');r.status=action;}else if(action==='완료'){if(r.status!=='수락됨')throw Error('수락된 교환만 완료할 수 있어요.');if(!r.confirmations.includes(user))r.confirmations.push(user);if(r.confirmations.length===2){r.status='교환 완료';data.books.filter(b=>[r.target,r.offered].includes(b.id)).forEach(b=>b.status='completed');}}}
export function contacts(data,r,user){if(!['수락됨','교환 완료'].includes(r.status)||![r.from,r.to].includes(user))return [];return [r.target,r.offered].map(id=>{const b=data.books.find(b=>b.id===id);return {name:data.users.find(u=>u.id===b.owner).nickname,method:b.method,value:b.contact};});}
